function render_route(string $path): void {
 if($path!=='/'&&str_ends_with($path,'/')){
  $clean=rtrim($path,'/');
  if(preg_match('#^/(?:products(?:/[a-z0-9-]+)?|categories/[0-9]+-[a-z0-9-]+|guides(?:/[a-z0-9-]+)?|articles(?:/[a-z0-9-]+)?|blog|plastic-products|wholesale-buying|shipping|terms|returns|payment-guide|about|contact|faq|privacy|wholesale)$#',$clean)){
   $query=parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_QUERY);
   redirect(url($clean).($query!==null&&$query!==false?'?'.$query:''),301);
  }
  $path=$clean;
 }
 if(str_starts_with($path,'/categories/')&&category_page($path))return;
 if($path==='/articles'){articles_page();return;}
 if($path==='/blog'){redirect('/articles',301);}
 if(preg_match('#^/articles/([a-z0-9-]+)$#',$path,$match)&&article_page($match[1]))return;
 if($path==='/guides'){guides_page();return;}
 if(preg_match('#^/guides/([a-z0-9-]+)$#',$path,$match)&&guide_page($match[1]))return;
 if($path==='/faq'){faq_page();return;}
 if($path==='/wholesale'){catalog_page('wholesale');return;}
 if($path==='/wholesale-panel'){redirect('/wholesale'.($_GET?'?'.http_build_query($_GET):''),302);}
 if($path==='/wholesale-buying'){require __DIR__.'/wholesale-page.php';wholesale_buying_page();return;}
 if($path==='/plastic-products'){plastic_sales_page();return;}
 if($path==='/shipping'){shipping_page();return;}
 if(in_array($path,['/terms','/returns','/payment-guide'],true)){legal_page($path);return;}
 if($path==='/robots.txt'){header('Content-Type: text/plain; charset=utf-8');echo "User-agent: *\nAllow: /\nDisallow: /install\nSitemap: ".url('/sitemap.xml');return;}
 if($path==='/sitemap.xml'){require_once __DIR__.'/sitemap.php';serve_sitemap();return;}
 if(preg_match('#^/sitemaps/(pages|products|categories|guides|articles)(?:-([2-9]|[1-9][0-9]+))?\.xml$#',$path,$match)){require_once __DIR__.'/sitemap.php';serve_sitemap_section($match[1],isset($match[2])?(int)$match[2]:1);return;}
 if($path==='/admin-2fa'){two_factor_login_page();return;}
 if($path==='/admin'){if((current_user()['role']??'')!=='ADMIN')redirect('/login');require __DIR__.'/admin.php';render_admin();return;}
 if($path==='/'){home_page();return;}
 if($path==='/products'){catalog_page();return;}
 if(preg_match('#^/products/([a-z0-9-]+)$#',$path,$m)){detail_page($m[1]);return;}
 if(in_array($path,['/cart','/checkout'],true)){cart_page($path==='/checkout');return;}
 if(in_array($path,['/login','/register'],true)){auth_page($path!=='/login');return;}
 if($path==='/forgot-password'){page_header('بازیابی رمز عبور','',false);echo '<div class="container page-content"><div class="panel auth-form"><h1>بازیابی رمز با پیامک</h1><p>ارسال پیامک هنوز توسط مدیر فروشگاه پیکربندی نشده است. برای بازیابی حساب با پشتیبانی تماس بگیرید.</p><a class="btn" href="/contact">تماس با پشتیبانی</a><a class="text-link" href="/login">بازگشت به ورود</a></div></div>';page_footer();return;}
 if($path==='/account'){account_page();return;}
 if($path==='/track'){track_page();return;}
 if(in_array($path,['/about','/contact','/faq','/privacy'],true)){info_page($path);return;}
 not_found_page();
}
