function catalog_page(string $buy='retail'): void {
 if($buy==='retail'&&($_GET['buy']??'')==='wholesale'){$filters=$_GET;unset($filters['buy']);redirect('/wholesale'.($filters?'?'.http_build_query($filters):''),302);}
 $basePath=$buy==='wholesale'?'/wholesale':'/products';$priceColumn=$buy==='wholesale'?'wholesale':'retail';
 $q=text_input('q',0,120,$_GET);$category=isset($_GET['category'])?number_input('category',0,PHP_INT_MAX,$_GET):0;$max=isset($_GET['max'])?number_input('max',0,100000000,$_GET):100000000;$sort=$_GET['sort']??'';$page=isset($_GET['page'])?number_input('page',1,100000,$_GET):1;$pageSize=24;$offset=($page-1)*$pageSize;
 $order=match($sort){'low'=>'p.'.$priceColumn.' ASC','high'=>'p.'.$priceColumn.' DESC',default=>'p.id DESC'};$where=' FROM ns_products p JOIN ns_categories c ON c.id=p.category_id WHERE p.active=1 AND p.'.$priceColumn.'<=?';$args=[$max];$where.= $buy==='wholesale'?" AND EXISTS (SELECT 1 FROM ns_product_sales s WHERE s.product_id=p.id AND s.sale_type='wholesale')":" AND NOT EXISTS (SELECT 1 FROM ns_product_sales s WHERE s.product_id=p.id AND s.sale_type='wholesale')";if($category){$where.=' AND p.category_id=?';$args[]=$category;}
 if($q===''){$total=(int)query('SELECT COUNT(*)'.$where,$args)->fetchColumn();$products=all('SELECT p.*,c.name category_name'.$where.' ORDER BY '.$order.' LIMIT '.$pageSize.' OFFSET '.$offset,$args);}else{require_once __DIR__.'/search-match.php';$matches=array_values(array_filter(search_products($q,500),fn($p)=>product_sales((int)$p['id'])['sale_type']===$buy&&(!$category||(int)$p['category_id']===$category)&&(int)$p[$priceColumn]<=$max));if($sort==='low'||$sort==='high')usort($matches,fn($a,$b)=>$sort==='low'?((int)$a[$priceColumn]<=>(int)$b[$priceColumn]):((int)$b[$priceColumn]<=>(int)$a[$priceColumn]));$total=count($matches);$products=array_slice($matches,$offset,$pageSize);}
 $pages=max(1,(int)ceil($total/$pageSize));if($page>$pages&&$total>0)redirect($basePath.'?'.http_build_query(array_merge($_GET,['page'=>$pages])),302);
 page_header($buy==='wholesale'?'محصولات عمده با قیمت عمده':'محصولات خرده','مقایسه و خرید انواع نایلون، نایلکس و محصولات بسته‌بندی با قیمت عمده و خرده.',!$q&&!$category&&!isset($_GET['max'])&&!isset($_GET['sort'])&&$page===1,url($basePath.($page>1?'?page='.$page:'')));?><div class="container page-content"><div class="page-heading"><h1><?=$buy==='wholesale'?'خرید عمده':'خرید خرده'?> محصولات</h1><span><?=money($total)?> محصول</span></div><?php sales_navigation();?><div class="catalog-layout"><form action="<?=h($basePath)?>" class="filter-panel"><?php hidden('buy',$buy);?><h2>فیلتر محصولات</h2><?php field('جستجو','q',$q,'text',false);?><label>دسته‌بندی<select name="category"><option value="0">همه دسته‌بندی‌ها</option><?php foreach(all('SELECT * FROM ns_categories')as$c):?><option value="<?=$c['id']?>" <?=$category==(int)$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><?php field('حداکثر قیمت (تومان)','max',$max,'number');?><label>مرتب‌سازی<select name="sort"><option value="">پیشنهاد فروشگاه</option><option value="low" <?=$sort==='low'?'selected':''?>>ارزان‌ترین</option><option value="high" <?=$sort==='high'?'selected':''?>>گران‌ترین</option></select></label><button class="btn">اعمال فیلتر</button><a href="<?=h($basePath)?>" class="text-link">حذف فیلترها</a></form><div><div class="product-grid catalog-grid"><?php foreach($products as$p)product_card($p);if(!$products):?><div class="empty-state"><h2>محصولی پیدا نشد</h2><p>شاید این دسته‌ها برایتان مناسب باشند.</p><div class="empty-links"><?php foreach(array_slice(seo_categories(),0,5)as$c):?><a href="<?=h($basePath.'?category='.$c['id'])?>"><?=h($c['name'])?></a><?php endforeach;?></div><a class="btn" href="<?=h($basePath)?>">نمایش همه محصولات</a></div><?php endif;?></div><?php if($pages>1):?><nav class="pagination" aria-label="صفحه‌بندی"><?php if($page>1):?><a href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">قبلی</a><?php endif;?><span>صفحه <?=money($page)?> از <?=money($pages)?></span><?php if($page<$pages):?><a href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">بعدی</a><?php endif;?></nav><?php endif;?></div></div></div><?php page_footer();
}
