 json_ld(['@context'=>'https://schema.org','@type'=>'Product','name'=>$p['name'],'description'=>$p['description'],'image'=>url($p['image']),'sku'=>(string)$p['id'],'category'=>$p['category_name'],'brand'=>['@type'=>'Brand','name'=>'نایلکس سادات','alternateName'=>'پلاستیک سادات'],'offers'=>['@type'=>'Offer','url'=>url('/products/'.$slug),'price'=>unit_price($p,1)*10,'priceCurrency'=>'IRR','availability'=>$p['stock']?'https://schema.org/InStock':'https://schema.org/OutOfStock','itemCondition'=>'https://schema.org/NewCondition','seller'=>['@type'=>'Organization','name'=>'نایلکس سادات']]]);
 json_ld(['@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'خانه','item'=>url('/')],['@type'=>'ListItem','position'=>2,'name'=>$p['category_name'],'item'=>url(category_path(['id'=>$p['category_id'],'name'=>$p['category_name']]))],['@type'=>'ListItem','position'=>3,'name'=>$p['name'],'item'=>url('/products/'.$slug)]]]);
 ?><div class="container page-content"><?php admin_edit_link('/admin?tab=products&edit='.$p['id'],'ویرایش این محصول');?><nav class="breadcrumbs" aria-label="مسیر صفحه"><a href="/">خانه</a> ← <a href="<?=h(category_path(['id'=>$p['category_id'],'name'=>$p['category_name']]))?>"><?=h($p['category_name'])?></a> ← <span aria-current="page"><?=h($p['name'])?></span></nav><div class="detail-grid"><div class="detail-image"><img src="<?=h($p['image'])?>" width="650" height="600" alt="<?=h($p['name'])?>"></div><div><span class="eyebrow"><?=h($p['category_name'])?></span><h1><?=h($p['name'])?></h1><h2>توضیحات محصول</h2><p class="detail-description"><?=nl2br(h($p['description']))?></p><?php render_product_features((int)$p['id']);?><div class="price-box"><span><?=is_wholesale_product($p)?'قیمت عمده':'قیمت خرده'?> هر <?=h($p['unit'])?></span><strong><?=money(unit_price($p,1))?> <small>تومان</small></strong><p><?php product_sales_hint($p);?></p></div><?php quantity_control($p,true);?><div class="product-stock-total"><span class="muted"><?=$p['stock']?'موجود در انبار':'ناموجود؛ محصولات مرتبط پایین صفحه را ببینید'?></span></div></div></div><?php product_seo_sections($p);product_reviews($p);?></div><?php page_footer();
}
function plastic_products_page(): void {$products=all('SELECT p.*,c.name category_name FROM ns_products p JOIN ns_categories c ON c.id=p.category_id WHERE p.active=1 ORDER BY p.featured DESC,p.stock>0 DESC,p.id DESC LIMIT 12');$categories=seo_categories();$title='فروش محصولات پلاستیکی سادات؛ خرید عمده و خرده';$description='خرید محصولات پلاستیکی سادات شامل نایلون، نایلکس، کیسه فریزر، کیسه زباله و لوازم بسته‌بندی با قیمت عمده و خرده و ارسال به سراسر کشور.';page_header($title,$description,true,url('/plastic-products'));json_ld(['@context'=>'https://schema.org','@type'=>'CollectionPage','name'=>$title,'description'=>$description,'url'=>url('/plastic-products'),'isPartOf'=>['@type'=>'WebSite','name'=>'نایلکس سادات','alternateName'=>['پلاستیک سادات','سادات پخش'],'url'=>url('/')],'mainEntity'=>['@type'=>'ItemList','itemListElement'=>array_map(fn($p,$i)=>['@type'=>'ListItem','position'=>$i+1,'name'=>$p['name'],'url'=>url('/products/'.$p['slug'])],$products,array_keys($products))]]);json_ld(['@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'خانه','item'=>url('/')],['@type'=>'ListItem','position'=>2,'name'=>'محصولات پلاستیکی سادات','item'=>url('/plastic-products')]]]);?><div class="container page-content"><nav class="breadcrumbs"><a href="/">خانه</a> ← <span aria-current="page">محصولات پلاستیکی سادات</span></nav><header class="seo-landing-head"><span class="eyebrow">فروشگاه پلاستیک سادات</span><h1><?=h($title)?></h1><p class="seo-intro"><?=h($description)?></p><div class="buy-row"><a class="btn" href="#plastic-products-list">مشاهده محصولات</a><a class="btn outline" href="/wholesale">قیمت ویژه همکاران</a></div></header><section class="panel seo-content"><h2>محصولات پلاستیکی موردنیاز خانه و کسب‌وکار</h2><p>این صفحه مسیر دسترسی به محصولات پلاستیکی نایلکس سادات است. کالاها بر اساس نوع مصرف، واحد فروش، موجودی و قیمت قابل مقایسه‌اند. برای خرید دقیق‌تر، ابتدا دسته محصول و سپس اندازه، جنس، ضخامت یا تعداد داخل بسته را بررسی کنید.</p><div class="guide-grid"><?php foreach($categories as$c):?><a class="panel seo-category-link" href="<?=h(category_path($c))?>"><strong>خرید <?=h($c['name'])?></strong><span>مشاهده قیمت و مدل‌های موجود ←</span></a><?php endforeach;?></div><h2>خرید عمده محصولات پلاستیکی</h2><p>قیمت عمده هر محصول و حداقل مقدار لازم در همان صفحه درج شده است. حساب همکار تأییدشده می‌تواند قیمت همکاری را بدون شرط تعداد دریافت کند. برای سفارش بسیار حجیم یا مشخصات ثبت‌نشده، شرایط باید پیش از پرداخت با پشتیبانی تأیید شود.</p><p><a href="/wholesale-buying">راهنمای خرید عمده پلاستیک</a> · <a href="/shipping">روش‌های ارسال</a> · <a href="/faq">پرسش‌های متداول</a></p></section><section id="plastic-products-list"><div class="section-heading"><div><span class="eyebrow">موجود در فروشگاه</span><h2>محصولات پیشنهادی پلاستیک سادات</h2></div><a href="/products">همه محصولات ←</a></div><div class="product-grid"><?php foreach($products as$p)product_card($p);?></div></section><section class="panel seo-content"><h2>پلاستیک سادات یا نایلکس سادات؟</h2><p>نام اصلی فروشگاه «نایلکس سادات» است و بعضی مشتریان آن را با عبارت‌های «پلاستیک سادات» یا «سادات پخش» جست‌وجو می‌کنند. همه این نام‌ها در این سایت به یک فروشگاه و مجموعه محصولات اشاره دارند.</p><h2>راهنمای انتخاب</h2><p>برای آشنایی با تفاوت مواد و انتخاب محصول مناسب، مقاله <a href="/guides/nylon-vs-nylex">تفاوت نایلون و نایلکس</a> را بخوانید. مشخصات واقعی هر کالا همیشه در صفحه محصول ملاک خرید است.</p></section></div><?php page_footer();}
function cart_page(bool $checkout): void {
 $lines=cart_lines();analytics_event($checkout?'checkout_view':'cart_view');$sum=0;$invalid=false;foreach($lines as$l){if(!empty($l['missing'])){$invalid=true;continue;}$sum+=(int)$l['price']*$l['quantity'];if($l['quantity']>$l['stock'])$invalid=true;}$s=settings();$shipping=shipping_cost($sum,$s);
 page_header($checkout?'تکمیل سفارش':'سبد خرید','',false,url($checkout?'/checkout':'/cart'));?><div class="container page-content"><?php if(!empty($_SESSION['cart_expired'])):unset($_SESSION['cart_expired']);?><p class="notice" role="status">سبد خرید پس از ۲۴ ساعت بدون تغییر خالی شد تا کالاهای قدیمی در آن باقی نمانند.</p><?php endif;?><div class="page-heading"><h1><?=$checkout?'تکمیل سفارش':'سبد خرید شما'?></h1><span class="muted">سبد خرید ← اطلاعات ارسال ← پرداخت</span></div><?php if(!$lines):?><div class="empty-state"><h2>سبد خرید خالی است</h2><p>سبد پس از ۲۴ ساعت بدون تغییر به‌صورت خودکار خالی می‌شود.</p><a class="btn" href="/products">مشاهده محصولات</a></div><?php else:?><div class="cart-layout"><div><?php if($checkout):$_SESSION['checkout_key']??=bin2hex(random_bytes(32));?><form method="post" id="checkout" class="panel form-stack" action="/checkout"><?php csrf_field();hidden('action','checkout');hidden('checkout_key',$_SESSION['checkout_key']);?><h2>اطلاعات گیرنده</h2><?php field('نام و نام خانوادگی','name',current_user()['name']??'');field('شماره موبایل','phone','','tel');textarea_field('نشانی کامل و کد پستی','address','',true);?><p class="muted">اطلاعات کارت فقط در صفحه درگاه وارد می‌شود.</p></form><?php else:?><div class="panel"><?php foreach($lines as$l):?><div class="cart-item"><?php if(!empty($l['missing'])):?><p>محصول دیگر در دسترس نیست.</p><?php else:?><img width="90" height="90" src="<?=h($l['image'])?>" alt="<?=h($l['name'])?>"><div class="cart-item-name"><?=h($l['name'])?><small><?=money($l['price'])?> تومان / <?=h($l['unit'])?></small></div><?php quantity_control($l);?><?php endif;action_start('cart_remove');hidden('id',$l['id']);?><button class="icon-button">حذف</button></form></div><?php endforeach;?></div><?php endif;?></div><aside class="panel order-summary"><h2>خلاصه سفارش</h2><p>مبلغ محصولات <b><?=money($sum)?> تومان</b></p><p>ارسال <b><?=$shipping?money($shipping).' تومان':'رایگان'?></b></p><?php if($s['free_above']):?><small>ارسال رایگان بالای <?=money($s['free_above'])?> تومان</small><?php endif;?><div class="summary-total"><span>مبلغ قابل پرداخت</span><strong><?=money($sum+$shipping)?> <small>تومان</small></strong></div><?php if($invalid):?><p class="error">موجودی بعضی محصولات کافی نیست؛ سبد را اصلاح کنید.</p><?php elseif($checkout):?><button form="checkout" class="btn">پرداخت و ثبت سفارش</button><?php else:?><a class="btn" href="/checkout">ادامه و تکمیل سفارش</a><?php endif;?><a href="/products" class="text-link">ادامه خرید</a></aside></div><?php endif;?></div><?php page_footer();
}
function auth_page(bool $register,bool $wholesale=false): void {$wholesale=false;
 if($signed=current_user()){
  page_header('حساب فعال','',false);?><div class="container page-content"><div class="panel form-stack auth-form"><h1>شما با حساب <?=h($signed['name'])?> وارد شده‌اید</h1><p>برای ورود یا ثبت‌نام با حساب دیگر، ابتدا از این حساب خارج شوید.</p><a class="btn" href="<?=$signed['role']==='ADMIN'?'/admin':'/account'?>">ادامه با حساب فعلی</a><?php action_start('switch_account','','/login');hidden('destination',$register?($wholesale?'/register?account=wholesale':'/register'):'/login');?><button class="btn outline">خروج و استفاده از حساب دیگر</button></form></div></div><?php page_footer();return;
 }
 $target=$register?($wholesale?'/wholesale':'/register'):'/login';
 page_header($register?'ساخت حساب کاربری':'ورود به حساب','',false,url($target));
 ?><div class="container page-content"><nav class="auth-tabs" aria-label="ورود و ثبت‌نام"><a href="/login" aria-current="<?=$register?'false':'page'?>">ورود به حساب موجود</a><a href="/register" aria-current="<?=$register?'page':'false'?>">ساخت حساب جدید</a></nav><?php action_start($register?'register':'login','panel form-stack auth-form',$target);?><h1><?=$register?($wholesale?'همکار نایلکس سادات شوید':'به خانواده نایلکس سادات بپیوندید'):'خوش آمدید'?></h1><p><?=$register?'خرید آسان‌تر، پیگیری سفارش‌ها و همراهی در هر خرید.':'برای ادامه خرید یا مدیریت فروشگاه وارد حساب خود شوید.'?></p><?php
 if($register){field('نام و نام خانوادگی','name');hidden('account_type',$wholesale?'wholesale':'retail');}
 ?><label><?=$register?'شماره موبایل':'نام کاربری / شماره موبایل'?><input name="username" value="<?=h($register?'':($_SESSION['login_username']??''))?>" required autocomplete="username" dir="ltr" <?=$register?'inputmode="tel" minlength="11" maxlength="11"':''?>></label><label>رمز عبور<?=$register?'؛ حداقل ۸ کاراکتر':''?><input name="password" type="password" required autocomplete="<?=$register?'new-password':'current-password'?>" <?=$register?'minlength="8" maxlength="72"':''?>></label><a class="text-link" href="/forgot-password">&#128273; بازیابی رمز با پیامک</a><small>اطلاعات حساب و سابقه ورود برای مدیریت حساب و امنیت ذخیره می‌شود. <a href="/privacy">جزئیات حریم خصوصی</a></small><button class="btn"><?=$register?'ساخت حساب کاربری':'ورود به حساب'?></button><a class="text-link" href="<?=$register?'/login':'/register'?>"><?=$register?'حساب دارید؟ وارد شوید':'حساب ندارید؟ ثبت‌نام کنید'?></a></form></div><?php page_footer();
}
function account_page(): void {$u=current_user();if(!$u)redirect('/login');page_header('حساب کاربری','',false,url('/account'));?><div class="container page-content"><div class="panel account-panel"><h1>سلام، <?=h($u['name'])?></h1><p>با همین حساب می‌توانید خرید خرده و عمده انجام دهید؛ قیمت عمده با رسیدن تعداد هر کالا به آستانه آن خودکار اعمال می‌شود.</p><?php if($u['role']==='ADMIN'):?><a class="btn" href="/admin">پنل مدیریت</a><?php endif;?><p><a class="btn" href="/wholesale">مشاهده محصولات عمده</a></p><h2>سفارش‌های شما</h2><?php $orders=all('SELECT code,status,total FROM ns_orders WHERE user_id=? ORDER BY id DESC LIMIT 30',[$u['id']]);foreach($orders as$o):?><p><a href="/track?code=<?=h($o['code'])?>"><?=h($o['code'])?> · <?=h(order_status($o['status']))?></a></p><?php endforeach;if(!$orders):?><div class="empty-state compact"><h3>هنوز سفارشی ندارید</h3><p>محصول موردنیازتان را انتخاب کنید؛ وضعیت سفارش‌های بعدی همین‌جا نمایش داده می‌شود.</p><a class="btn" href="/products">شروع خرید</a></div><?php endif;action_start('logout');?><button class="btn outline">خروج از حساب</button></form><?php password_form();?></div></div><?php page_footer();}
function track_page(): void {page_header('پیگیری سفارش','',false,url('/track'));?><div class="container page-content track-wrap"><?php action_start('track','panel form-stack','/track');?><h1>پیگیری سفارش</h1><p>کد سفارش و موبایل گیرنده را وارد کنید.</p><?php if(isset($_GET['payment'])):?><p class="notice">از درگاه برگشتید؛ برای مشاهده نتیجه قطعی، اطلاعات سفارش را وارد کنید.</p><?php endif;field('کد سفارش','code',is_string($_GET['code']??null)?$_GET['code']:($_SESSION['last_order']??''));field('شماره موبایل','phone','','tel');?><button class="btn">بررسی سفارش</button></form><?php if(isset($_SESSION['tracked_order'])):$o=one('SELECT id,code,total,status,reference FROM ns_orders WHERE id=?',[$_SESSION['tracked_order']]);if($o):?><div class="panel tracking-result"><span class="status"><?=h(order_status($o['status']))?></span><h2><?=h($o['code'])?></h2><?php foreach(all('SELECT name,quantity,price FROM ns_order_items WHERE order_id=?',[$o['id']])as$i):?><p><?=h($i['name'])?> × <?=money($i['quantity'])?><b><?=money($i['price']*$i['quantity'])?> تومان</b></p><?php endforeach;?><p>مبلغ کل با ارسال <b><?=money($o['total'])?> تومان</b></p><?php if($o['reference']):?><p>شناسه پرداخت: <?=h($o['reference'])?></p><?php endif;?></div><?php endif;endif;?></div><?php page_footer();}
function shipping_page(): void {$s=settings();$fields=['origin'=>'مبدأ ارسال','tehran_time'=>'زمان تقریبی تهران','other_time'=>'زمان تقریبی شهرستان','retail_methods'=>'روش ارسال سفارش عادی','wholesale_methods'=>'روش ارسال عمده','estimated_cost'=>'هزینه تقریبی'];$published=[];foreach($fields as$key=>$label){$value=content_text('shipping.'.$key,'');if($value!=='')$published[$label]=$value;}page_header('روش‌های ارسال','اطلاعات هزینه، مبدأ و روش ارسال سفارش‌های نایلکس سادات.',true,url('/shipping'));?><div class="container page-content"><article class="panel prose"><h1>روش‌های ارسال</h1><p>اطلاعات قطعی هر سفارش و هزینه نهایی پیش از پرداخت در سبد خرید نمایش داده می‌شود.</p><?php foreach($published as$label=>$value):?><h2><?=h($label)?></h2><p><?=nl2br(h($value))?></p><?php endforeach;?><h2>ارسال رایگان</h2><p><?=$s['free_above']?'برای سفارش‌های بالای '.money($s['free_above']).' تومان، هزینه ارسال در سبد رایگان محاسبه می‌شود.':'در حال حاضر آستانه ارسال رایگان تعریف نشده است.'?></p><?php if((current_user()['role']??'')==='ADMIN'):?><section class="shipping-editor"><h2>تکمیل اطلاعات ارسال</h2><p>فیلدهای خالی برای مشتری منتشر نمی‌شوند.</p><?php foreach($fields as$key=>$label)editable_text('shipping.'.$key,$label,content_text('shipping.'.$key,''));?></section><?php endif;?><a class="btn" href="/products">بازگشت به فروشگاه</a></article></div><?php page_footer();}
function not_found_page(string $title='محصول یا صفحه موردنظر پیدا نشد'): void {http_response_code(404);page_header($title,'',false);$categories=array_slice(seo_categories(),0,5);$best=all("SELECT p.*,c.name category_name FROM ns_products p JOIN ns_categories c ON c.id=p.category_id WHERE p.active=1 ORDER BY p.featured DESC,p.stock DESC,p.id DESC LIMIT 4");?><div class="container page-content"><section class="empty-state not-found"><h1><?=h($title)?></h1><p>نام محصول را جست‌وجو کنید یا از دسته‌بندی‌های پیشنهادی وارد فروشگاه شوید.</p><form action="/products" class="search not-found-search"><input name="q" required placeholder="جست‌وجوی محصول" aria-label="جست‌وجوی محصول"><button>جست‌وجو</button></form><div class="empty-links"><?php foreach($categories as$c):?><a href="<?=h(category_path($c))?>"><?=h($c['name'])?></a><?php endforeach;?></div><a class="btn" href="/products">بازگشت به فروشگاه</a></section><?php if($best):?><section><h2>محصولات پرفروش و پیشنهادی</h2><div class="product-grid"><?php foreach($best as$p)product_card($p);?></div></section><?php endif;?></div><?php page_footer();}
function info_page(string $path): void {$s=settings();$title=['/about'=>'درباره ما','/contact'=>'تماس با ما','/faq'=>'پرسش‌های متداول','/privacy'=>'حریم خصوصی'][$path];page_header($title,$title.' نایلکس سادات؛ راهنمای خرید و استفاده از خدمات.',true,url($path));?><div class="container page-content"><article class="panel prose"><span class="eyebrow">نایلکس سادات</span><h1><?=h($title)?></h1><?php if($path==='/about'):?><h2>همراه خانه و کسب‌وکار شما</h2><?php wholesale_terms();if($s['company_about']):?><p><?=nl2br(h($s['company_about']))?></p><?php else:?><p>نایلکس سادات فروشگاه محصولات پلاستیکی و بسته‌بندی است. هدف ما ساده‌تر کردن تهیه نیازهای روزمره، با امکان خرید خرده و عمده و قیمت‌گذاری شفاف است.</p><p>کیسه فریزر، کیسه زباله، نایلون و نایلکس را بر اساس نیازتان انتخاب کنید. در هر محصول، حداقل تعداد خرید عمده مشخص شده است.</p><?php endif;?><a class="btn" href="/products">مشاهده محصولات</a><?php elseif($path==='/contact'):?><h2><?=h($s['company_name'])?></h2><?php foreach(['company_phone'=>'تلفن','company_email'=>'ایمیل','company_address'=>'نشانی','company_hours'=>'ساعات پاسخ‌گویی','company_postal_code'=>'کد پستی']as$k=>$v)if($s[$k])echo '<p>'.h($v).' : '.h($s[$k]).'</p>';if(!$s['company_phone']&&!$s['company_address'])echo '<p>اطلاعات تماس به‌زودی تکمیل می‌شود.</p>';?><a class="btn" href="/track">پیگیری سفارش</a><?php elseif($path==='/privacy'):?><p>آخرین به‌روزرسانی: ۲۴ شهریور ۱۴۰۵</p><h2>چه داده‌هایی جمع‌آوری می‌شوند؟</h2><p>برای ساخت و مدیریت حساب، نام و شماره موبایل و رمز عبورِ هش‌شده ذخیره می‌شود. برای سفارش، نام گیرنده، شماره موبایل، نشانی، اقلام و مبالغ سفارش، وضعیت و شناسه پرداخت نگهداری می‌شود. اطلاعات کارت بانکی در سایت ذخیره نمی‌شود و فقط در درگاه پرداخت وارد می‌شود. برای امنیت حساب، زمان رویدادهای ورود، ثبت‌نام و تغییر رمز همراه با مشخصات اعلام‌شده مرورگر ثبت می‌شود.</p><h2>هدف استفاده</h2><p>این داده‌ها فقط برای ارائه حساب کاربری، ثبت و ارسال سفارش، پیگیری و پشتیبانی، پردازش پرداخت، جلوگیری از سوءاستفاده و انجام الزامات قانونی و مالی استفاده می‌شوند.</p><h2>مدت نگهداری</h2><p>کوکی نشست تا پایان نشست مرورگر و اعتبار ورود حداکثر ۲۴ ساعت است. سبد خرید در نشست نگهداری می‌شود. سابقه ورود حداکثر ۹۰ روز نگهداری می‌شود. اطلاعات حساب تا زمان درخواست حذف حساب باقی می‌ماند. سوابق سفارش و پرداخت تا زمانی که برای پیگیری سفارش و الزامات قانونی، مالی و حل اختلاف لازم باشد نگهداری می‌شوند.</p><h2>اشتراک‌گذاری و امنیت</h2><p>اطلاعات لازم برای پرداخت با ارائه‌دهنده درگاه پرداخت و اطلاعات لازم برای تحویل با ارائه‌دهنده ارسال به اشتراک گذاشته می‌شود. داده‌ها برای تبلیغات به فروش نمی‌رسند. دسترسی به اطلاعات به اشخاص مجاز محدود است و رمزها به‌صورت هش‌شده ذخیره می‌شوند.</p><h2>حقوق و تماس</h2><p>برای مشاهده، اصلاح یا درخواست حذف اطلاعات حساب با اطلاعات درج‌شده در صفحه تماس با ما ارتباط بگیرید. ممکن است نگهداری بخشی از سوابق سفارش به دلیل الزامات قانونی یا مالی ضروری باشد.</p><a class="btn" href="/contact">تماس با ما</a><?php else:foreach(['چطور با قیمت عمده خرید کنم؟'=>'با رسیدن تعداد هر محصول به حداقل خرید عمده، قیمت همکاری اعمال می‌شود. مشتریان عمده تأییدشده برای هر تعداد از آن استفاده می‌کنند.','هزینه ارسال چقدر است؟'=>'هزینه ارسال ثابت و حد ارسال رایگان در سبد نمایش داده می‌شود.','پرداخت ناموفق شد؛ چه کنم؟'=>'کد سفارش را نگه دارید و وضعیت آن را در پیگیری بررسی کنید. برای بررسی تراکنش با پشتیبانی تماس بگیرید.']as$q=>$a):?><details><summary><?=h($q)?></summary><p><?=h($a)?></p></details><?php endforeach;endif;?></article></div><?php page_footer();}
